from pathlib import Path
import json
r=Path(__file__).resolve().parents[2]
entries=[
('总览','overview','Harness：把各部分组织成运行系统',90,[155,156],'工具执行操作，Memory保存和取用信息，Skills提供可复用的方法，Protocols约定交互。Harness是围绕模型运行的一套程序，把这些组件接到组织输入、调用模型、安排执行、检查与继续的过程中。本节先看整体，再展开五类运行安排。'),
('总览','concept','一次任务，在Harness中怎样推进？',100,[156],'用户任务进入运行系统，Memory和Skills提供所需信息与方法，程序组织本次输入，模型据此生成回答或调用请求。工具实际执行，结果进入检查与下一轮输入。应用可以按模型输出或预设规则决定继续、等待或结束。通过协议连接外部服务是一种接入方式；本地工具也可由程序直接调用。'),
('总览','overview','让任务持续运行，还要解决哪些问题？',80,[157,159,185],'输入越来越长，需要压缩和清理；操作影响外部，需要范围与权限；固定环节反复出现，可以按事件触发；较大任务需要安排分工；中断后需要依据状态恢复。这五类安排都发生在模型之外，并共同支持运行循环。'),
('上下文','overview','上下文：下一次调用要带上什么？',90,[160,163],'上下文是本次模型调用能够看到的材料，包括任务、对话、工具说明与返回内容。任务推进时，网页、长日志和讨论会不断累积。Harness选择当前相关材料，摘要较早过程，清理已用过且后续不需要的长输出。保留任务所需信息比反复携带所有过程更重要。'),
('上下文','concept','上下文压缩：留下继续工作的要点',110,[161],'Compaction把较早的过程整理成工作摘要，留下目标、约束、关键数字、已完成事项、当前结论和未解决问题，供后续调用继续工作。摘要有取舍，遗漏关键条件会改变后续判断。生成摘要本身也有开销；它减少后续反复携带的历史。整个过程调整模型输入，没有把本次经历写进模型参数。'),
('上下文','summary','清理长输出，保留重新查阅的路径',100,[162],'重复搜索结果、已处理的长日志可以从后续输入移出，保留整理结果与原始地址或文件位置。原始资料仍在外部且可以访问时，需要细节再通过工具读取。压缩整理较早过程，清理移出已不需要的内容。Memory保存供以后使用的信息，上下文管理则决定当前调用实际带上哪些内容。'),
('沙盒与权限','overview','沙盒与权限：范围和放行分别管理',120,[164,165],'Sandbox通过运行环境限制受其约束的程序能够访问的文件与网络范围。图中配置为项目文件可读写、项目外个人资料不可访问、连接已允许网站。权限规则另行决定操作允许、要求确认或拒绝。需要确认沙盒实际覆盖哪些程序或工具，以及是否存在不同的执行路径。自然语言规则仍需要程序和环境落实。'),
('沙盒与权限','summary','人工确认：先核对这次要做什么',100,[166,167],'当发送邮件被安排为需要人工确认的操作时，应用暂停发送，展示收件人、正文、附件及影响。用户可以发送、修改或取消。一次放行只针对当前动作；保存为允许规则时，需要明确目标范围和生效条件。用户确认和沙盒边界共同约束实际执行，不能把允许一次理解为开放所有操作。'),
('Hooks','overview','Hooks：按事件触发预设动作',100,[176],'Hook把一个运行事件与预先配置的动作关联起来，发生事件且条件匹配时由应用触发。这里用命令型Hook解释选择事件、配置条件、指定程序，以及实际运行时的对应关系。格式整理、记录工具使用、固定检查都可以接到这样的触发点。Hook的核心是触发关系；它运行什么程序、是否还调用模型，取决于具体配置。'),
('Hooks','case','文件编辑后，自动整理格式',90,[177],'Claude Code的格式整理配置在Edit或Write工具成功后触发PostToolUse，运行Prettier处理刚编辑文件。触发条件是特定工具成功完成，处理对象来自该次工具输入。Prettier整理缩进和换行等格式。对内容准确性或程序功能的判断仍需按任务目标检查。把这一固定环节配置好，就可在匹配事件后直接触发。'),
('Hooks','summary','Hooks：执行前检查，执行后处理',100,[178],'要拦截写入受保护文件，应在执行前检查目标并阻止调用。执行后的Hook可整理或检查结果，但已发生的外部动作需要另外的修正或补救。Skill告诉模型工作方法，Hook把动作接到运行事件，工具或程序完成实际操作。事件、条件、动作以及触发时点共同决定Hook的作用。'),
('子智能体','overview','子智能体：把具体工作分出去',110,[180,181],'子智能体（Sub-agent）也称子代理。主代理委托范围明确的子任务，子代理在各自的上下文中处理并回传结果。主代理安排先后、汇总并检查，必要时追问或进一步读取材料。下面分别看过程隔离、依赖关系和分工开销。子智能体描述分工安排，A2A描述不同Agent服务间的任务交换约定；组织子智能体不必都使用A2A。'),
('子智能体','concept','过程留在子任务，结果交回主代理',100,[182],'子任务可能读很多文档、日志并进行多次尝试，主任务不必带上全部细节。交回主要发现、尚未解决的问题以及来源或文件位置，主代理可以先按简要结果继续，需要细节再追问或读取原文。上下文隔离减少主任务中积累的中间过程，也延续前面渐进式披露的思路。'),
('子智能体','concept','能否并行，先看任务之间的依赖',100,[183],'相互独立的两个检查可以并行，再汇总发现。修改依赖先找出问题，就按顺序执行。多个任务操作同一文件或同一业务对象时，还需划清修改范围、安排合并并重新检查。任务能被拆开与任务适合并行是两个不同的判断。'),
('子智能体','summary','什么时候值得把任务分出去？',100,[184],'范围清楚、过程较长、结论能简述的工作适合委托。很小的改动、频繁来回交流或不断共享同一材料的任务，直接处理往往更简单。子智能体会自行消耗Token与时间，主代理还需要汇总和检查。应一起比较上下文隔离、并行收益、结果质量与沟通开销，不能只看主上下文是否变短。'),
('进度与恢复','overview','保存进度，让下一次运行接得上',110,[170,171,172],'长任务把目标拆为可检查事项，持续记录已完成内容、工作文件、未解决问题与下一步，并在适当位置保存可恢复状态。下一次会话先读取进度，再检查当前文件和环境是否与记录一致，随后继续。进度说明、实际工作文件和检查结果相互对应，才能避免每次重新猜测上次做到哪里。'),
('进度与恢复','summary','恢复前，确认哪些动作已经发生',100,[173,174,175],'外部通知可能已经发出，只是在等待返回结果时中断。此时不能只凭没有收到响应就判断未执行；应查询发送状态或检查外部结果，再决定继续、重试或交给人处理。运行日志帮助定位问题，已保存状态支持恢复，检查结果帮助判断是否满足目标。若需要继续，具体问题再进入下一轮输入。'),
('小结','summary','Harness：把输入、执行与反馈接起来',100,[156,185],'回到章首同一张运行图：工具提供操作，Memory提供可取用的信息，Skills提供方法，Protocols约定外部交互，Harness将它们组织成运行循环。五类新增安排分别管理当前材料、操作范围、事件触发、任务分工与进度恢复。这些程序变化不直接改变模型参数；接下来再看如何把有效经验经过筛选和训练转为模型能力。')]
pages=[];materials={}
for i,(s,t,title,secs,src,talk) in enumerate(entries,1):
    p=8500+i
    pages.append(dict(page=p,renderer=p,navigation='3.5',section='Harness·'+s,type=t,title=title,seconds=secs,show_sources=False,on_slide=[title,talk],talk=talk,sources=[{'id':'HARNESS_R11','locator':'原课PDF物理第'+','.join(map(str,src))+'页'}]))
    materials[str(p)]=talk
out={'pages':pages,'materials':materials,'sources':{'HARNESS_R11':{'title':'Harness：原课配图、机制核对与适配记录','path':'sources/harness-r11/source-map.json','href':'sources/harness-r11/source-map.json'}}}
(r/'src/harness-r11.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
print(len(pages),'pages',sum(p['seconds'] for p in pages),'seconds')
